sys_ui_page.client_script:
function evMostrarErro(message) {
    var error = gel('ev_error');

    error.textContent = message;
    error.style.display = message ? 'block' : 'none';
}

function evConfirmar() {
    var message = gel('ev_message').value.trim();
    var error = gel('ev_error');

    if (message.length < 20) {
        evMostrarErro(
            'Informe pelo menos 20 caracteres.');
        return false;
    }

    var dialog = GlideModal.get();;
    var ga = new GlideAjax('EvSolicitarInformacoesAjax');

    ga.addParam('sysparm_name', 'solicitar');
    ga.addParam('sysparm_record_id',
        dialog.getPreference('sysparm_record_id'));
    ga.addParam('sysparm_message', message);

    evMostrarErro('');

    ga.getXMLAnswer(function(answer) {
        var result;

        try {
            result = JSON.parse(answer || '{}');
        } catch (e) {
            evMostrarErro('Erro ao processar solicitação.');
            return;
        }

        if (!result.success) {
            evMostrarErro(
                result.error || 'Não foi possível salvar.');
            return;
        }

        dialog.destroy();
        window.location.reload();
    });

    return false;
}

ga.getXMLAnswer(function (answer) {
    var result;

    try {
        result = JSON.parse(answer || '{}');
    } catch (e) {
        evMostrarErro('Resposta inválida: ' + answer);
        return;
    }

    if (!result.success) {
        evMostrarErro(
            result.error || 'Resposta do servidor: ' + answer
        );
        return;
    }

    dialog.destroy();
    window.location.reload();
});

function evCancelar() {
    GlideModal.get().destroy();
    return false;
}
